// 峡谷晨雾 / Gorge at Dawn — a painted gorge, baked to 16 colours, brought to life by the code.
//
// This one is not drawn procedurally. A painted plate was authored for the composition (old tree leaning in
// from the left, a pale misty gorge behind, a stepped cliff on the right with two falls, mossy stones in the
// foreground), then reduced to a 384 × 240 grid, 16 colours, ordered dither. That plate is shipped here as
// one 4-bit-per-pixel run: 46,080 bytes, 61,440 base64 characters — about 60 KB of source for a full-screen
// painting, which is the price of not faking the composition with noise.
//
// The code owns the one thing a still image cannot do: the water falls, the mist drifts, the light through the
// canopy breathes, and a few fireflies wander over the stones. Everything else is the baked plate, copied into
// the frame each draw with a single typed-array copy.
import { clamp, rand, hex, TAU, mix } from "../../../src/core/index.js";
import { clip } from "../../../src/fx/weather/_lib.js";

export const meta = {
  name: "Gorge at Dawn",
  desc: "A painted forest gorge at dawn: an old tree leaning over the left, a pale misty valley behind it, two falls dropping off the stepped cliff on the right, and dark mossy stones in the foreground. The plate is 16 colours and dithered; the water, mist, sunlight and fireflies move.",
  tags: ["gorge", "waterfall", "forest", "mist", "painting", "16 colours", "wide", "16:10", "ambient", "loop"],
  size: [384, 240],
  origin: [0, 0],
  duration: 16,
  loop: true,
  fps: 30,
  bg: "black",
  options: {
    other: ["#07100a", "#1a2418", "#39442f", "#5c6250", "#8a8a70", "#b9bda8", "#e6e8da", "#fbfdf4"],
    density: 1,
  },
};

const W = 384, H = 240;

// ---- the baked plate: 16 colours, 4 bits per pixel, base64 ------------------------------------
const PAL = ["#010401","#080c06","#121610","#1d231c","#2c342d","#40463a","#545d54","#6b6a48","#6a7570","#87845f","#828e8d","#ada373","#9ca9a5","#bcc0b0","#d7d9c8","#f8f9f2"];
const DATA = "";

let PLATE = null;
function plate() {
  if (PLATE) return PLATE;
  const raw = typeof atob === "function"
    ? atob(DATA)
    : Buffer.from(DATA, "base64").toString("binary");
  const lut = PAL.map((c) => {
    const n = parseInt(c.slice(1), 16);
    return ((n >> 16) & 255) | ((n >> 8) & 255) << 8 | (n & 255) << 16 | 255 << 24;
  });
  const out = new Uint32Array(W * H);
  const idx = new Uint8Array(W * H);
  let k = 0;
  for (let i = 0; i < W * H; i += 2) {
    const b = raw.charCodeAt(k++);
    idx[i] = b >> 4; out[i] = lut[b >> 4];
    idx[i + 1] = b & 15; out[i + 1] = lut[b & 15];
  }
  PLATE = { w: W, h: H, color: out, idx };
  return PLATE;
}

// ---- where the water is: taken off the plate itself ---------------------------------------------
// The falls are the brightest, least saturated pixels on the cliff. Masking by that instead of by
// hand-measured boxes means the streaks line up with the painted water wherever it actually is.
let WET = null;
function wet() {
  if (WET) return WET;
  const P = plate();
  const lum = PAL.map((c) => {
    const n = parseInt(c.slice(1), 16);
    return 0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255);
  });
  // a tall run of bright pixels in a column is water; a short bright patch is fog. Without this the
  // streaks drift over the mist to the left of the falls and read as static.
  const col = new Uint16Array(W);
  for (let y = 2; y < 202; y++) for (let x = 236; x < W; x++) {
    if (lum[P.idx[y * W + x]] >= 202) col[x]++;
  }
  const list = [];
  for (let x = 236; x < W; x++) {
    if (col[x] < 26) continue;
    for (let y = 2; y < 202; y++) {
      const i = y * W + x;
      if (lum[P.idx[i]] >= 202) list.push(i);
    }
  }
  WET = list;
  return WET;
}

const WHITE = "#fbfdf4", PALE = "#dfe6d8", FOAM = "#c6d2c4";

export function drawBack(p, t, o) {
  const q = clip(p, meta);
  const P = plate();
  if (q.w === P.w && q.h === P.h) q.C.set(P.color);
  p.L.fill(0);
  water(q, t, o.density || 1);
  mist(q, t, o.density || 1);
  sun(q, t);
}

export function draw(p, t, o) {
  const q = clip(p, meta);
  flies(q, t, o.density || 1);
  lamp(q, t);
}

// ---- the falls: a scrolling streak pattern, drawn only where the plate has water ---------------
function water(q, t, dn) {
  const L = wet();
  const speed = 24 * (1 + dn * 0.15);
  for (let n = 0; n < L.length; n++) {
    const i = L[n];
    const x = i % W, y = (i - x) / W;
    // Two offsets: one per column, so neighbouring columns fall at slightly different rates and the
    // bands drift diagonally; one per pixel, so band edges are ragged instead of level.
    const cs = Math.sin(x * 12.9898) * 43758.5453;
    const ps = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
    const jc = (cs - Math.floor(cs)) * 11;
    const jp = (ps - Math.floor(ps)) * 6;
    const ph = (y + t * speed + jc + jp) % 30;
    if (ph < 2) q.blend(x, y, WHITE, 0.6 * dn);            // the bright lip of a band
    else if (ph < 10) q.blend(x, y, "#b3bfb4", 0.3 * dn);  // the shading behind it
  }
}
// ---- mist: low banks drifting across the gorge floor, and a thin veil at the falls --------------
function mist(q, t, dn) {
  const MIST = "#cfd9c6";
  const BANKS = [
    { y: 172, rx: 74, ry: 9, x0: -30, x1: 300, per: 14, a: 0.1 },
    { y: 190, rx: 56, ry: 7, x0: 40, x1: 340, per: 11, a: 0.09 },
    { y: 146, rx: 44, ry: 6, x0: 120, x1: 300, per: 16, a: 0.06 },
  ];
  for (const B of BANKS) {
    for (let i = 0; i < 2; i++) {
      const ph = ((t / B.per) + i * 0.5) % 1;
      const x = B.x0 + ph * (B.x1 - B.x0) + i * 60;
      const a = B.a * Math.sin(Math.PI * ph) * dn;
      for (let y = Math.floor(B.y - B.ry); y <= B.y + B.ry; y++)
        for (let xx = Math.floor(x - B.rx); xx <= x + B.rx; xx++) {
          const dx = (xx - x) / B.rx, dy = (y - B.y) / B.ry;
          const d2 = dx * dx + dy * dy;
          if (d2 > 1) continue;
          q.blend(xx, y, MIST, a * (1 - d2));
        }
    }
  }
  // the veil that always hangs where the lower fall lands
  for (let i = 0; i < 3; i++) {
    const x = 300 + i * 9 + Math.sin(t * 0.4 + i) * 3;
    const y = 150 + i * 5;
    q.disc(x, y, 9 + i * 2, () => MIST, (d) => 0.07 * (1 - d) * dn);
  }
}

// ---- sunlight through the canopy: three shafts that breathe ------------------------------------
function sun(q, t) {
  const SHAFTS = [{ x: 26, w: 26, lean: 40 }, { x: 66, w: 16, lean: 30 }, { x: 118, w: 12, lean: 52 }];
  for (let s = 0; s < SHAFTS.length; s++) {
    const S = SHAFTS[s];
    const pulse = 0.5 + 0.5 * Math.sin(TAU * t / 8 + s * 1.9);
    for (let y = 0; y < 186; y++) {
      const k = (1 - clamp((y - 96) / 90, 0, 1)) * clamp(y / 26, 0, 1);
      if (k <= 0) continue;
      const cx = S.x + y * (S.lean / 190);
      for (let i = -S.w / 2; i <= S.w / 2; i += 1.2) {
        const d = Math.abs(i) / (S.w / 2);
        const a = k * (1 - d) * (0.05 + pulse * 0.05);
        if (a > 0.01) q.light(cx + i, y, "#fff2c8", a);
      }
    }
  }
}

// ---- fireflies over the stones, and the small warm lamp -------------------------------------
function flies(q, t, dn) {
  const n = Math.round(4 + dn * 5);
  for (let i = 0; i < n; i++) {
    const per = 6 + rand(431, i, 1) * 6;
    const u = (t / per) % 1;
    const x = 60 + rand(431, i, 2) * 250 + Math.sin(u * TAU * 2 + i) * 9;
    const y = 186 + rand(431, i, 3) * 44 + Math.cos(u * TAU * 3 + i) * 5;
    const a = Math.sin(Math.PI * u) * (0.4 + 0.4 * Math.sin(TAU * t / 4 + i * 2));
    if (a <= 0.04) continue;
    q.add(x, y, "#ffe58f", a * 0.55);
    q.light(x, y, "#ffd27a", a * 0.2);
  }
}

function lamp(q, t) {
  const flick = 0.82 + 0.18 * Math.sin(TAU * t / 2) + 0.06 * Math.sin(TAU * t * 3);
  q.add(150, 196, "#ffb84d", 0.5 * flick);
  q.light(150, 197, "#ffb84d", 0.22 * flick);
}
